function createCommunityWall() {
  const wall = Array.from({ length: 25 }, (_, index) => ({ ...communityFeed[index % communityFeed.length] }));
  const availableIndices = Array.from({ length: wall.length }, (_, index) => index);

  for (let index = availableIndices.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [availableIndices[index], availableIndices[swapIndex]] = [availableIndices[swapIndex], availableIndices[index]];
  }

  oneOffCommunityInserts.forEach((item, index) => {
    wall[availableIndices[index]] = item;
  });

  const uploadedIndices = [...availableIndices];
  for (let index = uploadedIndices.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [uploadedIndices[index], uploadedIndices[swapIndex]] = [uploadedIndices[swapIndex], uploadedIndices[index]];
  }

  uploadedCommunityItems.forEach((item, index) => {
    wall[uploadedIndices[index]] = item;
  });

  return wall;
}

