function CommunityCampaignBanner({ onSelect }) {
  const [activeCampaign, setActiveCampaign] = useState(0);
  const [campaignPaused, setCampaignPaused] = useState(false);

  useEffect(() => {
    if (campaignPaused) return undefined;
    const timer = window.setInterval(() => {
      setActiveCampaign((index) => (index + 1) % campaignBanners.length);
    }, 4200);
    return () => window.clearInterval(timer);
  }, [campaignPaused]);

  const currentCampaign = campaignBanners[activeCampaign];

  return (
    <article
      className="community-campaign-banner"
      aria-label="活动轮播"
      aria-roledescription="carousel"
      onMouseEnter={() => setCampaignPaused(true)}
      onMouseLeave={() => setCampaignPaused(false)}
    >
      <div className="campaign-banner-media" aria-hidden="true">
        {campaignBanners.map((campaign, index) => (
          <img
            className={index === activeCampaign ? "is-active" : ""}
            src={campaign.image}
            alt=""
            key={campaign.title}
          />
        ))}
      </div>
      <div className="campaign-banner-content">
        <strong>{currentCampaign.title}</strong>
        <button type="button" onClick={() => onSelect(currentCampaign)}>
          {currentCampaign.action}
          <ArrowRight size={12} weight="bold" />
        </button>
      </div>
      <button
        className="campaign-banner-arrow is-previous"
        type="button"
        aria-label="上一个活动"
        onClick={() => setActiveCampaign((index) => (
          index - 1 + campaignBanners.length
        ) % campaignBanners.length)}
      >
        <CaretLeft size={18} weight="bold" />
      </button>
      <button
        className="campaign-banner-arrow is-next"
        type="button"
        aria-label="下一个活动"
        onClick={() => setActiveCampaign((index) => (
          index + 1
        ) % campaignBanners.length)}
      >
        <CaretRight size={18} weight="bold" />
      </button>
      <div className="campaign-banner-dots" aria-label="切换活动">
        {campaignBanners.map((campaign, index) => (
          <button
            type="button"
            className={index === activeCampaign ? "is-active" : ""}
            aria-label={`查看${campaign.title}`}
            aria-current={index === activeCampaign ? "true" : undefined}
            onClick={() => setActiveCampaign(index)}
            key={campaign.title}
          />
        ))}
      </div>
    </article>
  );
}

function CommunityInspirationCard({ item, onOpen }) {
  return (
    <article
      className={`community-card ${item.layout}`}
      role="button"
      tabIndex={0}
      aria-label={`查看灵感作品：${item.title}`}
      onClick={() => onOpen(item)}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          onOpen(item);
        }
      }}
    >
      <img src={item.image} alt={item.title} />
      <CommunityProgressiveBlur />
      <div className="community-body">
        <div className="community-footer">
          <span className="community-author-mark" aria-hidden="true">
            <img src={item.image} alt="" />
          </span>
          <span>{item.author.slice(0, 7)}</span>
          <span className="community-like-count" aria-label={"点赞 " + item.likes}>
            <Heart size={18} weight="fill" />
            {item.likes}
          </span>
        </div>
      </div>
    </article>
  );
}

function InspirationDetailModal({ item, onClose, onRemix, onReference }) {
  if (!item) return null;

  return (
    <div
      className="inspiration-detail-overlay"
      role="presentation"
      onClick={onClose}
    >
      <section
        className="inspiration-detail-card"
        role="dialog"
        aria-modal="true"
        aria-labelledby="inspiration-detail-title"
        onClick={(event) => event.stopPropagation()}
      >
        <button
          className="inspiration-detail-close"
          type="button"
          onClick={onClose}
          aria-label="关闭灵感详情"
        >
          <X size={20} />
        </button>

        <div className="inspiration-detail-image">
          <img src={item.image} alt={item.title} />
        </div>

        <div className="inspiration-detail-content">
          <span className="inspiration-detail-eyebrow">Inspiration Detail</span>
          <h2 id="inspiration-detail-title">{item.title}</h2>
          <div className="inspiration-detail-meta">
            <span>{item.author}</span>
            <span>{item.likes} 喜欢</span>
          </div>
          <div className="inspiration-detail-prompt">
            <span><Sparkle size={15} weight="fill" /> 生图提示词</span>
            <p>{item.prompt}</p>
          </div>
          <div className="inspiration-detail-actions">
            <button className="inspiration-remix-button" type="button" onClick={() => onRemix(item)}>
              <MagicWand size={18} weight="fill" />
              做同款
            </button>
            <button className="inspiration-reference-button" type="button" onClick={() => onReference(item)}>
              <ImageSquare size={18} />
              作为参考图
            </button>
          </div>
        </div>
      </section>
    </div>
  );
}

