function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function FlowingMeshBackground() {
  return (
    <div className="flowing-mesh-bg" aria-hidden="true">
      <MeshGradient
        className="flowing-mesh-shader"
        width="150%"
        height="150%"
        worldWidth={1280}
        worldHeight={720}
        colors={["#e5e5e5", "#5f38ff", "#ff5dbb", "#7f2bd8", "#8ae2ff"]}
        distortion={0.55}
        swirl={0}
        grainMixer={0}
        grainOverlay={0}
        speed={0.65}
        scale={0.68}
        offsetX={0.32}
        fit="cover"
      />
    </div>
  );
}

function formatCurrency(value) {
  return new Intl.NumberFormat("zh-CN", {
    style: "currency",
    currency: "CNY",
    maximumFractionDigits: 0,
  }).format(value);
}

function getSavedIntents() {
  try {
    return JSON.parse(localStorage.getItem("ai-zaowu-intents") || "[]");
  } catch {
    return [];
  }
}

function createCategoryGeometry(THREE, shape) {
  if (shape === "sphere") return new THREE.DodecahedronGeometry(0.92, 2);
  if (shape === "cup") return new THREE.CylinderGeometry(0.58, 0.52, 1.18, 36, 1);
  if (shape === "badge") return new THREE.CylinderGeometry(0.82, 0.82, 0.16, 56, 1);
  if (shape === "print3d") return new THREE.IcosahedronGeometry(0.9, 1);
  if (shape === "cylinder") return new THREE.CylinderGeometry(0.72, 0.88, 1.16, 24, 1);
  if (shape === "torus") return new THREE.TorusKnotGeometry(0.56, 0.16, 72, 8);
  return new THREE.BoxGeometry(1.34, 1.02, 0.46, 3, 3, 2);
}

function createRoundedPlateGeometry(THREE, width, height, depth, radius) {
  const halfWidth = width / 2;
  const halfHeight = height / 2;
  const cornerRadius = Math.min(radius, halfWidth, halfHeight);
  const shape = new THREE.Shape();

  shape.moveTo(-halfWidth + cornerRadius, -halfHeight);
  shape.lineTo(halfWidth - cornerRadius, -halfHeight);
  shape.quadraticCurveTo(halfWidth, -halfHeight, halfWidth, -halfHeight + cornerRadius);
  shape.lineTo(halfWidth, halfHeight - cornerRadius);
  shape.quadraticCurveTo(halfWidth, halfHeight, halfWidth - cornerRadius, halfHeight);
  shape.lineTo(-halfWidth + cornerRadius, halfHeight);
  shape.quadraticCurveTo(-halfWidth, halfHeight, -halfWidth, halfHeight - cornerRadius);
  shape.lineTo(-halfWidth, -halfHeight + cornerRadius);
  shape.quadraticCurveTo(-halfWidth, -halfHeight, -halfWidth + cornerRadius, -halfHeight);

  const geometry = new THREE.ExtrudeGeometry(shape, {
    depth,
    steps: 1,
    curveSegments: 12,
    bevelEnabled: true,
    bevelSegments: 3,
    bevelSize: Math.min(depth * 0.32, cornerRadius * 0.22),
    bevelThickness: depth * 0.28,
  });
  geometry.translate(0, 0, -depth / 2);
  geometry.rotateY(Math.PI / 2);
  geometry.computeVertexNormals();
  return geometry;
}

const gltfCache = new Map();
const customPrintTextureUrl = "/assets/custom-print-rabbit.png";
const customPrintAspectRatio = 680 / 640;

function loadGltfModel(GLTFLoader, url) {
  if (!gltfCache.has(url)) {
    const loader = new GLTFLoader();
    const promise = loader.loadAsync(url).catch((error) => {
      gltfCache.delete(url);
      throw error;
    });
    gltfCache.set(url, promise);
  }
  return gltfCache.get(url);
}

function fitModelToStage(THREE, object, targetSize) {
  object.position.set(0, 0, 0);
  object.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(object);
  const size = new THREE.Vector3();
  const center = new THREE.Vector3();
  box.getSize(size);

  const maxAxis = Math.max(size.x, size.y, size.z) || 1;
  object.scale.setScalar(targetSize / maxAxis);
  object.updateMatrixWorld(true);

  const scaledBox = new THREE.Box3().setFromObject(object);
  scaledBox.getCenter(center);
  object.position.sub(center);
}

function createCustomPrintTexture(THREE) {
  const texture = new THREE.TextureLoader().load(customPrintTextureUrl);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.anisotropy = 4;
  return texture;
}

function lockTexturedMaterialColor(THREE, material, color) {
  if (!material || !color || !material.map) return;

  material.map.colorSpace = THREE.SRGBColorSpace;
  material.map.needsUpdate = true;
  material.color?.set?.("#ffffff");
  material.toneMapped = true;
  if ("roughness" in material) material.roughness = Math.max(material.roughness ?? 0.5, 0.72);
  if ("metalness" in material) material.metalness = 0;

  if (material.emissive?.set) {
    material.emissive.set("#000000");
    material.emissiveIntensity = 0;
  }
}

function addInactiveColorReveal(THREE, material, initialReveal, inactiveColor = "#d7d7dc") {
  const revealUniform = { value: initialReveal };
  const inactiveColorUniform = { value: new THREE.Color(inactiveColor) };
  material.userData.colorRevealUniform = revealUniform;
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uColorReveal = revealUniform;
    shader.uniforms.uInactiveModelColor = inactiveColorUniform;
    shader.fragmentShader = `uniform float uColorReveal;\nuniform vec3 uInactiveModelColor;\n${shader.fragmentShader}`;
    shader.fragmentShader = shader.fragmentShader.replace(
      "#include <color_fragment>",
      "#include <color_fragment>\ndiffuseColor.rgb = mix(uInactiveModelColor, diffuseColor.rgb, uColorReveal);",
    );
  };
  material.needsUpdate = true;
  return revealUniform;
}

function CategoryModel({ product, isActive, snapActive = false, showPrint = true, interactive = true, onReady }) {
  const canvasRef = useRef(null);
  const activeRef = useRef(isActive);
  const snapActiveRef = useRef(snapActive);
  const parallaxRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    activeRef.current = isActive;
  }, [isActive]);

  useEffect(() => {
    if (snapActive) {
      snapActiveRef.current = true;
    }
  }, [snapActive]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return undefined;

    let frame = 0;
    let disposed = false;
    let renderer;
    const disposables = [];

    async function setupScene() {
      const gltfVariants = product.model.variants?.length
        ? product.model.variants
        : product.model.url
          ? [{ url: product.model.url }]
          : [];
      const [THREE, loaderModule] = await Promise.all([
        import("three"),
        gltfVariants.length ? import("three/examples/jsm/loaders/GLTFLoader.js") : Promise.resolve(null),
      ]);
      if (disposed) return;

      try {
        renderer = new THREE.WebGLRenderer({
          canvas,
          alpha: true,
          antialias: true,
          powerPreference: "low-power",
        });
      } catch (error) {
        console.warn("Category model renderer unavailable, using image fallback.", error);
        return;
      }
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.5));
      renderer.outputColorSpace = THREE.SRGBColorSpace;
      renderer.toneMapping = THREE.ACESFilmicToneMapping;
      renderer.toneMappingExposure = 1.08;

      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 24);
      camera.position.set(0, 0, 4.95);

      const group = new THREE.Group();
      scene.add(group);
      const materialRevealers = [];
      const colorShiftMaterials = [];
      const inactivePlateItems = [];
      const detailedModelRoots = [];
      const detailedModelMaterials = [];
      const inactiveModelColor = product.model.inactiveColor ?? "#d7d7dc";
      let currentMaterialReveal = activeRef.current ? 1 : 0;
      let currentMaterialColorShift = activeRef.current ? 1 : 0;

      let hasLoadedModel = false;
      if (gltfVariants.length && loaderModule?.GLTFLoader) {
        for (const variant of gltfVariants) {
          try {
            const gltf = await loadGltfModel(loaderModule.GLTFLoader, variant.url);
            if (disposed) return;

            const modelRoot = gltf.scene.clone(true);
            modelRoot.rotation.set(
              variant.rotationX ?? product.model.rotationX ?? 0,
              variant.rotationY ?? product.model.rotationY ?? -Math.PI / 2,
              variant.rotationZ ?? product.model.rotationZ ?? 0,
            );
            modelRoot.traverse((node) => {
              if (!node.isMesh) return;
              node.frustumCulled = true;
              const preserveMaterial = variant.preserveMaterial ?? product.model.preserveMaterial;
              if (preserveMaterial) {
                const prepareMaterial = (sourceMaterial) => {
                  const material = sourceMaterial?.clone ? sourceMaterial.clone() : sourceMaterial;
                  if (!material) return material;
                  material.side = THREE.DoubleSide;
                  lockTexturedMaterialColor(THREE, material, variant.lockColor ?? product.model.lockColor);
                  if (!variant.inactivePlate && (variant.whiteWhenInactive ?? product.model.whiteWhenInactive)) {
                    materialRevealers.push(addInactiveColorReveal(THREE, material, currentMaterialReveal, inactiveModelColor));
                  }
                  if (variant.inactivePlate) {
                    const baseOpacity = material.opacity ?? 1;
                    material.transparent = true;
                    material.opacity = baseOpacity * currentMaterialReveal;
                    material.depthWrite = currentMaterialReveal > 0.98;
                    detailedModelMaterials.push({ material, baseOpacity });
                  }
                  material.needsUpdate = true;
                  disposables.push(material);
                  return material;
                };
                const coloredMaterials = Array.isArray(node.material)
                  ? node.material.map(prepareMaterial)
                  : prepareMaterial(node.material);

                node.material = coloredMaterials;
                return;
              }
              const isMug = product.id === "mug";
              const baseColor = isMug ? "#f8f8f5" : variant.color ?? product.model.color ?? "#ffffff";
              const material = new THREE.MeshPhysicalMaterial({
                color: new THREE.Color(baseColor),
                roughness: isMug ? 0.32 : 0.38,
                metalness: 0,
                clearcoat: isMug ? 0.38 : 0.22,
                clearcoatRoughness: isMug ? 0.22 : 0.32,
                sheen: isMug ? 0.08 : 0.18,
                sheenColor: new THREE.Color("#ffffff"),
                reflectivity: isMug ? 0.34 : 0.24,
                side: THREE.DoubleSide,
              });
              colorShiftMaterials.push({
                material,
                inactiveColor: new THREE.Color(inactiveModelColor),
                activeColor: new THREE.Color(variant.activeColor ?? product.model.activeColor ?? baseColor),
              });
              if (variant.inactivePlate) {
                const baseOpacity = material.opacity ?? 1;
                material.transparent = true;
                material.opacity = baseOpacity * currentMaterialReveal;
                material.depthWrite = currentMaterialReveal > 0.98;
                detailedModelMaterials.push({ material, baseOpacity });
              }
              node.material = material;
              disposables.push(material);
            });
            fitModelToStage(THREE, modelRoot, variant.targetSize ?? product.model.targetSize ?? 2.06);
            const [offsetX = 0, offsetY = -0.12, offsetZ = 0] = variant.offset ?? product.model.offset ?? [];
            modelRoot.position.x += offsetX;
            modelRoot.position.y += offsetY;
            modelRoot.position.z += offsetZ;
            group.add(modelRoot);
            if (variant.inactivePlate) {
              modelRoot.visible = currentMaterialReveal > 0.01;
              detailedModelRoots.push(modelRoot);

              const plateConfig = variant.inactivePlate;
              const plateGeometry = createRoundedPlateGeometry(
                THREE,
                plateConfig.width,
                plateConfig.height,
                plateConfig.depth ?? 0.09,
                plateConfig.radius ?? 0.14,
              );
              const plateMaterial = new THREE.MeshPhysicalMaterial({
                color: new THREE.Color(plateConfig.color ?? "#eef0f4"),
                roughness: 0.36,
                metalness: 0.02,
                clearcoat: 0.44,
                clearcoatRoughness: 0.3,
                transparent: true,
                opacity: 1,
                side: THREE.DoubleSide,
              });
              const plate = new THREE.Mesh(plateGeometry, plateMaterial);
              plate.rotation.set(
                variant.rotationX ?? product.model.rotationX ?? 0,
                variant.rotationY ?? product.model.rotationY ?? -Math.PI / 2,
                variant.rotationZ ?? product.model.rotationZ ?? 0,
              );
              plate.position.set(offsetX, offsetY, offsetZ);
              plateMaterial.opacity = 1 - currentMaterialReveal;
              plateMaterial.depthWrite = currentMaterialReveal < 0.02;
              plate.visible = currentMaterialReveal < 0.99;
              group.add(plate);
              inactivePlateItems.push({ root: plate, material: plateMaterial });
              disposables.push(plateGeometry, plateMaterial);
            }
            hasLoadedModel = true;
          } catch (error) {
            console.warn(`Category model failed to load: ${variant.url}`, error);
          }
        }
      }

      if (!hasLoadedModel) {
        const material = new THREE.MeshPhysicalMaterial({
          color: new THREE.Color(inactiveModelColor),
          roughness: 0.34,
          metalness: 0.02,
          clearcoat: 0.5,
          clearcoatRoughness: 0.28,
        });
        colorShiftMaterials.push({
          material,
          inactiveColor: new THREE.Color(inactiveModelColor),
          activeColor: new THREE.Color(product.model.activeColor ?? product.model.color),
        });
        const geometry = createCategoryGeometry(THREE, product.model.shape);
        if (product.model.shape === "badge") {
          const edgeGeometry = new THREE.EdgesGeometry(geometry, 18);
          const edgeMaterial = new THREE.LineBasicMaterial({
            color: 0xd7dbe3,
            transparent: true,
            opacity: 0.52,
          });
          [
            { position: [-0.28, -0.04, 0.04], scale: 0.86, rotationZ: -0.08 },
            { position: [0.34, 0.18, -0.05], scale: 0.76, rotationZ: 0.12 },
          ].forEach(({ position, scale, rotationZ }) => {
            const badge = new THREE.Mesh(geometry, material);
            badge.position.set(...position);
            badge.rotation.set(Math.PI / 2, 0, rotationZ);
            badge.scale.setScalar(scale);
            group.add(badge);

            const badgeEdge = new THREE.LineSegments(edgeGeometry, edgeMaterial);
            badgeEdge.position.set(...position);
            badgeEdge.rotation.set(Math.PI / 2, 0, rotationZ);
            badgeEdge.scale.setScalar(scale);
            group.add(badgeEdge);
          });
          disposables.push(geometry, material, edgeGeometry, edgeMaterial);
        } else {
          const mesh = new THREE.Mesh(geometry, material);
          group.add(mesh);
          disposables.push(geometry, material);
        }

        if (product.model.shape === "cup") {
          const handleGeometry = new THREE.TorusGeometry(0.28, 0.055, 18, 36);
          const handle = new THREE.Mesh(handleGeometry, material);
          handle.position.set(0.55, 0.03, 0);
          handle.rotation.y = Math.PI / 2;
          group.add(handle);
          disposables.push(handleGeometry);
        }

        if (product.model.shape !== "badge") {
          const accentGeometry = new THREE.SphereGeometry(0.13, 18, 12);
          const accentMaterial = new THREE.MeshStandardMaterial({
            color: new THREE.Color(inactiveModelColor),
            emissive: new THREE.Color("#000000"),
            emissiveIntensity: 0,
            roughness: 0.38,
          });
          colorShiftMaterials.push({
            material: accentMaterial,
            inactiveColor: new THREE.Color(inactiveModelColor),
            activeColor: new THREE.Color(product.model.accent),
          });
          const accent = new THREE.Mesh(accentGeometry, accentMaterial);
          accent.position.set(0.62, 0.54, 0.42);
          group.add(accent);
          disposables.push(accentGeometry, accentMaterial);

          const edgeGeometry = new THREE.EdgesGeometry(geometry, 18);
          const edgeMaterial = new THREE.LineBasicMaterial({
            color: product.id === "hoodie" ? 0xffffff : 0x9aa7c8,
            transparent: true,
            opacity: product.id === "hoodie" ? 0.16 : 0.46,
          });
          const edges = new THREE.LineSegments(edgeGeometry, edgeMaterial);
          group.add(edges);
          disposables.push(edgeGeometry, edgeMaterial);
        }
      }

      const hemiLight = new THREE.HemisphereLight(0xffffff, 0xe9e5f2, 1.18);
      scene.add(hemiLight);
      const keyLight = new THREE.DirectionalLight(0xffffff, 3.95);
      keyLight.position.set(-4.2, 2.3, 3.2);
      scene.add(keyLight);
      const fillLight = new THREE.DirectionalLight(0xf3f6ff, 0.34);
      fillLight.position.set(3.2, 0.25, 2.1);
      scene.add(fillLight);
      const activeRimLight = new THREE.DirectionalLight(0xd7c8ff, 0);
      activeRimLight.position.set(3.6, 1.4, 2.5);
      scene.add(activeRimLight);
      const activeFrontLight = new THREE.PointLight(0xffffff, 0, 3.2);
      activeFrontLight.position.set(0.1, -0.15, 2.1);
      scene.add(activeFrontLight);

      const shouldShowCustomPrint = showPrint && !product.model.preserveMaterial;
      let patch;
      let patchMaterial;
      if (shouldShowCustomPrint) {
        const patchTexture = createCustomPrintTexture(THREE);
        const patchWidth = product.model.print?.width ?? 0.52;
        const patchPosition = product.model.print?.position ?? [0.01, 0.08, 0.59];
        const patchGeometry = new THREE.PlaneGeometry(patchWidth, patchWidth / customPrintAspectRatio);
        patchMaterial = new THREE.MeshBasicMaterial({
          map: patchTexture,
          transparent: true,
          opacity: activeRef.current ? 1 : 0,
          alphaTest: 0.02,
          depthTest: false,
          depthWrite: false,
          side: THREE.DoubleSide,
          toneMapped: false,
        });
        patch = new THREE.Mesh(patchGeometry, patchMaterial);
        patch.position.set(...patchPosition);
        patch.renderOrder = 10;
        group.add(patch);
        disposables.push(patchGeometry, patchMaterial, patchTexture);
      }

      const inactiveModelScale = product.model.inactiveScale ?? 0.86;
      const activeModelScale = product.model.activeScale ?? inactiveModelScale * 1.27;
      const activeModelLift = product.model.activeLift ?? 0.4;
      let currentModelScale = activeRef.current ? activeModelScale : inactiveModelScale;
      let currentModelLift = activeRef.current ? activeModelLift : 0;
      let currentPatchOpacity = activeRef.current && shouldShowCustomPrint ? 1 : 0;
      let currentLightBoost = activeRef.current ? 1 : 0;

      function resize() {
        const width = Math.max(1, canvas.clientWidth);
        const height = Math.max(1, canvas.clientHeight);
        if (canvas.width !== Math.floor(width * renderer.getPixelRatio()) || canvas.height !== Math.floor(height * renderer.getPixelRatio())) {
          renderer.setSize(width, height, false);
          camera.aspect = width / height;
          camera.updateProjectionMatrix();
        }
      }

      let hasReportedReady = false;

      function animate() {
        if (disposed) return;
        frame = requestAnimationFrame(animate);
        if (document.hidden) return;
        resize();
        const targetMaterialReveal = activeRef.current ? 1 : 0;
        if (snapActiveRef.current) {
          currentMaterialReveal = targetMaterialReveal;
        } else {
          currentMaterialReveal += (targetMaterialReveal - currentMaterialReveal) * 0.11;
        }
        if (materialRevealers.length) {
          materialRevealers.forEach((uniform) => {
            uniform.value = currentMaterialReveal;
          });
        }
        const targetMaterialColorShift = activeRef.current ? 1 : 0;
        if (colorShiftMaterials.length) {
          if (snapActiveRef.current) {
            currentMaterialColorShift = targetMaterialColorShift;
          } else {
            currentMaterialColorShift += (targetMaterialColorShift - currentMaterialColorShift) * 0.12;
          }
          colorShiftMaterials.forEach(({ material, inactiveColor, activeColor }) => {
            material.color.copy(inactiveColor).lerp(activeColor, currentMaterialColorShift);
          });
        }
        const targetModelScale = activeRef.current ? activeModelScale : inactiveModelScale;
        if (snapActiveRef.current) {
          currentModelScale = targetModelScale;
        } else {
          currentModelScale += (targetModelScale - currentModelScale) * 0.12;
        }
        group.scale.setScalar(currentModelScale);
        const targetModelLift = activeRef.current ? activeModelLift : 0;
        if (snapActiveRef.current) {
          currentModelLift = targetModelLift;
        } else {
          currentModelLift += (targetModelLift - currentModelLift) * 0.12;
        }
        const targetLightBoost = activeRef.current ? 1 : 0;
        if (snapActiveRef.current) {
          currentLightBoost = targetLightBoost;
        } else {
          currentLightBoost += (targetLightBoost - currentLightBoost) * 0.08;
        }
        const preservedMaterialLightSoftener = product.model.preserveMaterial ? 0.84 : 1;
        hemiLight.intensity = (1.18 + currentLightBoost * 0.08) * preservedMaterialLightSoftener;
        keyLight.intensity = (3.95 + currentLightBoost * 0.45) * preservedMaterialLightSoftener;
        fillLight.intensity = (0.34 + currentLightBoost * 0.1) * preservedMaterialLightSoftener;
        activeRimLight.intensity = currentLightBoost * (product.model.preserveMaterial ? 0.42 : 1.1);
        activeFrontLight.intensity = currentLightBoost * (product.model.preserveMaterial ? 0.08 : 0.22);
        renderer.toneMappingExposure = product.model.preserveMaterial ? 0.92 : 0.98 + currentLightBoost * 0.04;
        const targetPatchOpacity = activeRef.current && shouldShowCustomPrint ? 1 : 0;
        if (snapActiveRef.current) {
          currentPatchOpacity = targetPatchOpacity;
          snapActiveRef.current = false;
        } else {
          currentPatchOpacity += (targetPatchOpacity - currentPatchOpacity) * 0.16;
        }
        if (!activeRef.current) currentPatchOpacity = 0;
        if (inactivePlateItems.length) {
          const detailOpacity = Math.max(0, Math.min(1, currentMaterialReveal));
          detailedModelRoots.forEach((root) => {
            root.visible = detailOpacity > 0.01;
          });
          detailedModelMaterials.forEach(({ material, baseOpacity }) => {
            material.opacity = baseOpacity * detailOpacity;
            material.depthWrite = detailOpacity > 0.98;
          });
          inactivePlateItems.forEach(({ root, material }) => {
            const plateOpacity = 1 - detailOpacity;
            material.opacity = plateOpacity;
            material.depthWrite = plateOpacity > 0.98;
            root.visible = plateOpacity > 0.01;
          });
        }
        if (patch && patchMaterial) {
          patch.visible = activeRef.current;
          patchMaterial.opacity = currentPatchOpacity;
        }
        const targetRotationY = parallaxRef.current.x * 0.22;
        const targetRotationX = -parallaxRef.current.y * 0.14;
        group.rotation.y += (targetRotationY - group.rotation.y) * 0.1;
        group.rotation.x += (targetRotationX - group.rotation.x) * 0.1;
        group.position.y = currentModelLift;
        renderer.render(scene, camera);
        if (!hasReportedReady) {
          hasReportedReady = true;
          onReady?.(true);
        }
      }

      animate();
    }

    setupScene();

    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      disposables.forEach((item) => item.dispose());
      if (renderer) {
        renderer.dispose();
        renderer.forceContextLoss?.();
      }
    };
  }, [product, showPrint, onReady]);

  function handlePointerMove(event) {
    const rect = event.currentTarget.getBoundingClientRect();
    parallaxRef.current = {
      x: ((event.clientX - rect.left) / rect.width - 0.5) * 2,
      y: ((event.clientY - rect.top) / rect.height - 0.5) * 2,
    };
  }

  function handlePointerLeave() {
    parallaxRef.current = { x: 0, y: 0 };
  }

  return (
    <canvas
      className="category-model-canvas"
      ref={canvasRef}
      aria-hidden="true"
      onPointerMove={interactive ? handlePointerMove : undefined}
      onPointerLeave={interactive ? handlePointerLeave : undefined}
    />
  );
}

const WORKBENCH_CATEGORY_SHOWCASE_DELAY = 2300;
const WORKBENCH_CATEGORY_SHOWCASE_DURATION = 930;

function WorkbenchCategoryShowcase() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [carouselMotion, setCarouselMotion] = useState(null);
  const prepareTimerRef = useRef(0);
  const motionTimerRef = useRef(0);
  const motionDirection = carouselMotion?.phase === "moving"
    ? carouselMotion.direction
    : 0;
  const focusIndex = getCategoryIndex(activeIndex + motionDirection);
  const visibleCategorySlots = carouselMotion
    ? carouselMotion.direction > 0
      ? [-2, -1, 0, 1, 2, 3]
      : [-3, -2, -1, 0, 1, 2]
    : [-2, -1, 0, 1, 2];

  useEffect(() => {
    if (carouselMotion) return undefined;

    const timer = window.setTimeout(() => {
      const id = Date.now();
      setCarouselMotion({ direction: 1, phase: "prepare", id });
      prepareTimerRef.current = window.setTimeout(() => {
        setCarouselMotion((motion) => (
          motion?.id === id ? { ...motion, phase: "moving" } : motion
        ));
      }, 32);
      motionTimerRef.current = window.setTimeout(() => {
        setActiveIndex((index) => index + 1);
        setCarouselMotion(null);
      }, WORKBENCH_CATEGORY_SHOWCASE_DURATION);
    }, WORKBENCH_CATEGORY_SHOWCASE_DELAY);

    return () => window.clearTimeout(timer);
  }, [activeIndex, carouselMotion]);

  useEffect(() => () => {
    window.clearTimeout(prepareTimerRef.current);
    window.clearTimeout(motionTimerRef.current);
  }, []);

  return (
    <div
      className="category-stage workbench-category-showcase"
      aria-label="3D 品类自动轮播"
      aria-roledescription="carousel"
    >
      <style>{`
        .creative-visual-panel.is-category-unselected {
          grid-template-rows: minmax(0, 1fr);
          background: #f2f2f4;
        }

        .creative-product-stage.is-category-showcase {
          position: relative;
          width: 100%;
          height: 100%;
          min-width: 0;
          min-height: 0;
          overflow: hidden;
        }

        .workbench-category-showcase {
          width: 91.2%;
          max-width: 1344px;
          height: 100%;
          min-height: 0;
          margin: 0 auto;
          padding: 0;
          overflow: hidden;
          pointer-events: none;
          user-select: none;
        }

        .workbench-category-showcase::before,
        .workbench-category-showcase::after {
          top: 18%;
          bottom: 18%;
        }

        .workbench-category-showcase .category-track {
          position: absolute;
          top: 42%;
          right: 0;
          left: 0;
          width: 100%;
          height: 700px;
          min-height: 700px;
          margin: 0;
          padding: 0;
          transform: translateY(-50%) scale(1.2);
          transform-origin: center center;
          mask-image: linear-gradient(90deg, transparent 0%, #000 8%, #000 92%, transparent 100%);
          -webkit-mask-image: linear-gradient(90deg, transparent 0%, #000 8%, #000 92%, transparent 100%);
        }

        .workbench-category-showcase .category-float-item {
          bottom: 70px;
          width: clamp(204px, 19vw, 246px);
          transform:
            translateX(calc(-50% + ((var(--slot, 0) + var(--track-shift, 0)) * clamp(232px, 20.8vw, 276px)) + var(--item-x-adjust, 0px)))
            translateY(var(--item-y, 0px))
            translateZ(var(--item-depth, 0px))
            rotateY(var(--item-tilt, 0deg))
            scale(var(--item-scale, 1));
        }

        .workbench-category-showcase .category-action {
          display: none !important;
        }

        @media (max-width: 1180px) {
          .workbench-category-showcase .category-track {
            transform: translateY(-50%) scale(1.152);
          }
        }

        @media (max-width: 860px) {
          .workbench-category-showcase {
            min-height: 680px;
          }

          .workbench-category-showcase .category-track {
            transform: translateY(-50%) scale(1.128);
          }
        }

        @media (prefers-reduced-motion: reduce) {
          .workbench-category-showcase .category-float-item {
            transition-duration: 1ms !important;
          }
        }
      `}</style>

      <div className={`category-track ${
        carouselMotion?.phase === "moving" ? "is-moving-next" : ""
      }`}>
        {visibleCategorySlots.map((slot) => {
          const itemIndex = getCategoryIndex(activeIndex + slot);
          const item = categories[itemIndex];
          const targetSlot = slot - motionDirection;
          const depth = Math.min(3, Math.abs(targetSlot));
          const isFocused = focusIndex === itemIndex && depth <= 2;
          const isOuterRight = targetSlot === 2;
          const isOuterLeft = targetSlot === -2;
          const itemOpacity = depth === 0 ? 1 : depth === 1 ? 0.86 : depth === 2 ? 0.42 : 0;
          const itemScale = depth === 0 ? 1 : depth === 1 ? 0.94 : depth === 2 ? 0.82 : 0.74;
          const tiltAmount = depth === 1 ? 18 : depth === 2 ? 30 : 0;
          const depthOffset = depth === 1 ? -34 : depth === 2 ? -82 : 0;
          const verticalOffset = depth === 1 ? 10 : depth === 2 ? 22 : 0;
          const itemTilt = isFocused || targetSlot === 0
            ? 0
            : targetSlot < 0
              ? -tiltAmount
              : tiltAmount;
          const outerSpacingAdjustment = depth === 2
            ? (targetSlot < 0 ? 42 : -42)
            : 0;

          return (
            <div
              className={`category-float-item category-${item.id} ${
                isFocused ? "is-active" : ""
              } ${depth === 3 ? "is-edge" : ""} ${
                isOuterLeft ? "is-outer-left" : ""
              } ${isOuterRight ? "is-outer-right" : ""}`}
              style={{
                "--slot": slot,
                "--item-opacity": itemOpacity,
                "--item-scale": itemScale,
                "--item-tilt": `${itemTilt}deg`,
                "--item-depth": `${depthOffset}px`,
                "--item-y": `${verticalOffset}px`,
                "--item-x-adjust": `${outerSpacingAdjustment}px`,
                "--item-mobile-x-adjust": "0px",
                "--item-origin": targetSlot < 0
                  ? "right center"
                  : targetSlot > 0
                    ? "left center"
                    : "center center",
                zIndex: 20 - depth,
              }}
              aria-hidden={!isFocused}
              key={`${activeIndex + slot}-${item.id}`}
            >
              <span className="category-dot-texture" aria-hidden="true" />
              <div className="model-stage">
                <span className="model-ground-shadow" aria-hidden="true" />
                <CategoryModel
                  product={item}
                  isActive={isFocused}
                  snapActive={false}
                  interactive={false}
                />
              </div>
              <div className="category-title-row">
                <span className="category-name">{item.name}</span>
                <span className="category-price">
                  <span className="category-currency-symbol">¥</span>
                  <span className="category-price-number">{item.basePrice}</span>
                  {item.id === "print3d" && (
                    <span className="category-price-suffix">起</span>
                  )}
                </span>
              </div>
              <span className="category-caption">{item.highlight}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

