function ProductOutline({ productId, compact = false }) {
  const paths = productOutlinePaths[productId] || productOutlinePaths.tshirt;

  if (productId === "tshirt" && !compact) {
    return (
      <img
        className="product-outline product-outline-image"
        src="https://xiamingjun-project.oss-cn-hangzhou.aliyuncs.com/%E7%81%B5%E6%84%9F%E9%80%A0%E7%89%A9/assets/workbench-tshirt-outline.png"
        alt="白色T恤正面预览"
        draggable="false"
      />
    );
  }

  return (
    <svg
      className={`product-outline ${compact ? "is-compact" : ""}`}
      viewBox="0 0 240 260"
      fill="none"
      aria-hidden="true"
    >
      <g
        stroke="currentColor"
        strokeWidth={compact ? 4.2 : 2.1}
        strokeLinecap="round"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
      >
        {paths.map((path, index) => <path d={path} key={index} />)}
      </g>
    </svg>
  );
}

