  const [referenceImages, setReferenceImages] = useState([]);
  const [selectedThemePlay, setSelectedThemePlay] = useState(null);
  const [creativeConversationStarted, setCreativeConversationStarted] = useState(false);
  const [themePickerOpen, setThemePickerOpen] = useState(false);
  const [creativeTurns, setCreativeTurns] = useState([]);
  const [referenceDragActive, setReferenceDragActive] = useState(false);
  const [promptInspirationIndex, setPromptInspirationIndex] = useState(-1);
  const [communityTab, setCommunityTab] = useState("featured");
  const [communitySearchOpen, setCommunitySearchOpen] = useState(false);
  const [communitySearchTerm, setCommunitySearchTerm] = useState("");
  const [promptDockVisible, setPromptDockVisible] = useState(false);
  const [generationState, setGenerationState] = useState("idle");
  const [notice, setNotice] = useState("");
  const [cornerTip, setCornerTip] = useState("");
  const [patternPlacement, setPatternPlacement] = useState(defaultPatternPlacement);
  const [tshirtPrintStyle, setTshirtPrintStyle] = useState("large");
  const [patternDragging, setPatternDragging] = useState(false);
  const [patternSnap, setPatternSnap] = useState({ x: false, y: false });
  const [simulatorModelReady, setSimulatorModelReady] = useState(false);
  const [quantity, setQuantity] = useState(initialQuantity);
  const [orderDetails, setOrderDetails] = useState({
    purpose: "部门活动伴手礼",
    date: "2026-07-18",
    note: "",
  });
  const [addresses, setAddresses] = useState(() => {
    try {
      return JSON.parse(localStorage.getItem("ai-zaowu-addresses")) || [];
    } catch {
      return [];
    }
  });
  const [selectedAddressId, setSelectedAddressId] = useState(null);
  const [addressDraft, setAddressDraft] = useState({ name: "", phone: "", region: "", detail: "" });
  const [addressEditorOpen, setAddressEditorOpen] = useState(false);
  const [agreed, setAgreed] = useState(true);
  const [intents, setIntents] = useState([]);
  const [studioStage, setStudioStage] = useState("design");
  const [mockupState, setMockupState] = useState("idle");
  const [agentStory, setAgentStory] = useState(null);
  const [profileOpen, setProfileOpen] = useState(false);
  const [profileClosing, setProfileClosing] = useState(false);
  const [ordersOpen, setOrdersOpen] = useState(false);
  const [assetsOpen, setAssetsOpen] = useState(false);
  const [addressesOpen, setAddressesOpen] = useState(false);
  const [inspirationDetail, setInspirationDetail] = useState(null);
  const [openDockMenu, setOpenDockMenu] = useState(null);
  const [closingDockMenu, setClosingDockMenu] = useState(null);
  const [hoveredCategory, setHoveredCategory] = useState(null);
  const [categoryInteracting, setCategoryInteracting] = useState(false);
  const [carouselMotion, setCarouselMotion] = useState(null);
  /* waterfall interaction bridge v1 */
  useEffect(() => {
    function handleWaterfallRemake(event) {
      const item = event.detail;
      if (!item) return;

      if (item.prompt) setPrompt(item.prompt);
      if (item.model) setImageModel(item.model);
      if (item.size) setImageSize(item.size);
      if (item.quality) setImageQuality(item.quality);

      document.documentElement.classList.add("is-waterfall-remake-applying");
      setPromptDockVisible(true);
      const releaseRemakeMotionLock = () => {
        document.documentElement.classList.remove(
          "is-waterfall-remake-applying"
        );
      };
      window.requestAnimationFrame(() => {
        window.requestAnimationFrame(releaseRemakeMotionLock);
      });
      window.setTimeout(releaseRemakeMotionLock, 120);
      setInspirationDetail(null);
      setOpenDockMenu(null);
      setClosingDockMenu(null);
      setNotice(
        `已应用「${item.title || "同款作品"}」的提示词与生成参数，可继续编辑。`
      );
      window.setTimeout(() => promptDockInputRef.current?.focus(), 80);
    }

    function handleWaterfallOpen(event) {
      const item = event.detail?.item;
      if (!item) return;
      setOpenDockMenu(null);
      setClosingDockMenu(null);
      setInspirationDetail(item);
    }

    window.addEventListener("ai-zaowu:waterfall-remake", handleWaterfallRemake);
    window.addEventListener("ai-zaowu:waterfall-open", handleWaterfallOpen);
    return () => {
      document.documentElement.classList.remove("is-waterfall-remake-applying");
      window.removeEventListener("ai-zaowu:waterfall-remake", handleWaterfallRemake);
      window.removeEventListener("ai-zaowu:waterfall-open", handleWaterfallOpen);
    };
  }, []);

  const burstTimerRef = useRef(0);
  const carouselTimerRef = useRef(0);
  const carouselPrepareTimerRef = useRef(0);
  const categoryWheelResetTimerRef = useRef(0);
  const categoryWheelUnlockTimerRef = useRef(0);
  const categoryWheelDeltaRef = useRef(0);
  const categoryWheelLockedRef = useRef(false);
  const dockMenuTimerRef = useRef(0);
  const workbenchTransitionTimerRef = useRef(0);
  const workbenchTransitionSettleTimerRef = useRef(0);
  const mockupTimerRef = useRef(0);
  const profileMenuTimerRef = useRef(0);
  const categoryStageRef = useRef(null);
  const communitySectionRef = useRef(null);
  const communityDiscoveryRef = useRef(null);
  const promptDockRef = useRef(null);
  const sizeChartRef = useRef(null);
  const introSectionRef = useRef(null);
  const packagingSectionRef = useRef(null);
  const promptDockInputRef = useRef(null);
  const promptDockReferenceInputRef = useRef(null);
  const directPatternInputRef = useRef(null);
  const communitySearchInputRef = useRef(null);
  const referenceDragDepthRef = useRef(0);
  const creativeChatBodyRef = useRef(null);
  const printAreaRef = useRef(null);
  const patternDragRef = useRef(null);
  const motionDirection = carouselMotion?.phase === "moving" ? carouselMotion.direction : 0;
  const focusIndex = hoveredCategory ?? getCategoryIndex(activeIndex + motionDirection);
  const dotIndex = getCategoryIndex(hoveredCategory ?? activeIndex + motionDirection);
  const visibleCategorySlots = carouselMotion
    ? carouselMotion.direction > 0
      ? [-2, -1, 0, 1, 2, 3]
      : [-3, -2, -1, 0, 1, 2]
    : [-2, -1, 0, 1, 2];
  const visibleCommunityColumns = useMemo(() => {
    const normalizedSearch = communitySearchTerm.trim().toLocaleLowerCase("zh-CN");
    let items = communityTab === "latest" ? [...communityWall].reverse() : [...communityWall];

    if (communityTab === "events") {
      items = items.filter((_, index) => index % 3 === 0);
    }

    if (normalizedSearch) {
      items = items.filter((item) =>
        [item.title, item.author, item.prompt, ...(item.tags ?? [])]
          .join(" ")
          .toLocaleLowerCase("zh-CN")
          .includes(normalizedSearch),
      );
    }

    const columns = Array.from({ length: 6 }, () => []);
    items.forEach((item, index) => columns[index % columns.length].push({ item, index }));
    return columns;
  }, [communitySearchTerm, communityTab]);

  const openCommunitySearch = () => {
    setCommunitySearchOpen(true);
    window.requestAnimationFrame(() => communitySearchInputRef.current?.focus());
  };

  const closeCommunitySearch = () => {
    setCommunitySearchOpen(false);
    setCommunitySearchTerm("");
  };

  useEffect(() => {
    setIntents(getSavedIntents());
  }, []);

  useEffect(() => {
    localStorage.setItem("ai-zaowu-addresses", JSON.stringify(addresses));
    if (!selectedAddressId && addresses.length > 0) {
      setSelectedAddressId(addresses.find((address) => address.isDefault)?.id ?? addresses[0].id);
    }
  }, [addresses, selectedAddressId]);

  useEffect(() => {
    setSimulatorModelReady(false);
  }, [selectedProduct.id]);

  useEffect(() => () => {
    window.clearTimeout(burstTimerRef.current);
    window.clearTimeout(carouselTimerRef.current);
    window.clearTimeout(carouselPrepareTimerRef.current);
    window.clearTimeout(categoryWheelResetTimerRef.current);
    window.clearTimeout(categoryWheelUnlockTimerRef.current);
    window.clearTimeout(dockMenuTimerRef.current);
    window.clearTimeout(workbenchTransitionTimerRef.current);
    window.clearTimeout(workbenchTransitionSettleTimerRef.current);
    window.clearTimeout(mockupTimerRef.current);
    window.clearTimeout(profileMenuTimerRef.current);
  }, []);

  useEffect(() => {
    const stage = categoryStageRef.current;
    if (!stage || currentView !== "home") return undefined;

    const wheelListener = (event) => handleCategoryWheel(event);
    stage.addEventListener("wheel", wheelListener, { passive: false });
    return () => stage.removeEventListener("wheel", wheelListener);
  }, [currentView, activeIndex, carouselMotion]);

  useEffect(() => {
    if (!creativeConversationStarted || themePickerOpen) return undefined;
    const animationFrame = window.requestAnimationFrame(() => {
      const chatBody = creativeChatBodyRef.current;
      chatBody?.scrollTo({ top: chatBody.scrollHeight, behavior: "smooth" });
    });
    return () => window.cancelAnimationFrame(animationFrame);
  }, [creativeConversationStarted, creativeTurns, generationState, notice, themePickerOpen]);

  useEffect(() => {
    const section = communitySectionRef.current;
    const discoveryControl = communityDiscoveryRef.current;
    if (!section || !discoveryControl) return undefined;

    let animationFrame = 0;
    const updatePromptDockVisibility = () => {
      window.cancelAnimationFrame(animationFrame);
      animationFrame = window.requestAnimationFrame(() => {
        const discoveryRect = discoveryControl.getBoundingClientRect();
        const sectionRect = section.getBoundingClientRect();
        const nearTopLine = 96;
        setPromptDockVisible(
          discoveryRect.top <= nearTopLine && sectionRect.bottom > nearTopLine,
        );
      });
    };

    updatePromptDockVisibility();
    window.addEventListener("scroll", updatePromptDockVisibility, { passive: true });
    window.addEventListener("resize", updatePromptDockVisibility);

    return () => {
      window.cancelAnimationFrame(animationFrame);
      window.removeEventListener("scroll", updatePromptDockVisibility);
      window.removeEventListener("resize", updatePromptDockVisibility);
    };
  }, []);

  useEffect(() => {
    const promptMenuHostIsActive = (
      (
        promptDockVisible
        && currentView === "home"
        && !assetsOpen
        && !ordersOpen
        && !addressesOpen
      )
      || (
        currentView === "studio"
        && studioStage === "design"
        && !assetsOpen
        && !ordersOpen
        && !addressesOpen
      )
    );

    if (!promptMenuHostIsActive && openDockMenu) {
      closePromptDockMenu();
    }
  }, [
    promptDockVisible,
    currentView,
    studioStage,
    assetsOpen,
    ordersOpen,
    addressesOpen,
    openDockMenu,
  ]);

  useEffect(() => {
    if (!inspirationDetail) return undefined;
    const previousOverflow = document.body.style.overflow;
    const handleKeyDown = (event) => {
      if (event.key === "Escape") setInspirationDetail(null);
    };

    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", handleKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [inspirationDetail]);

  useEffect(() => {
    if (!profileOpen) return undefined;

    const handleProfileDismiss = (event) => {
      if (event.type === "keydown" && event.key !== "Escape") return;
      if (event.type === "pointerdown" && event.target.closest?.(".app-profile")) return;
      closeProfileMenu();
    };

    window.addEventListener("pointerdown", handleProfileDismiss);
    window.addEventListener("keydown", handleProfileDismiss);
    return () => {
      window.removeEventListener("pointerdown", handleProfileDismiss);
      window.removeEventListener("keydown", handleProfileDismiss);
    };
  }, [profileOpen, profileClosing]);

  useEffect(() => {
    if (!openDockMenu) return undefined;
    const closeDockMenu = (event) => {
      if (event.type === "keydown" && event.key !== "Escape") return;
      if (event.type === "pointerdown" && (
        event.target.closest?.(".prompt-dock-select-trigger")
        || event.target.closest?.(".prompt-dock-select-menu")
      )) return;
      closePromptDockMenu();
    };
    window.addEventListener("pointerdown", closeDockMenu);
    window.addEventListener("keydown", closeDockMenu);
    return () => {
      window.removeEventListener("pointerdown", closeDockMenu);
      window.removeEventListener("keydown", closeDockMenu);
    };
  }, [openDockMenu]);

  const totalQuantity = useMemo(
    () => Object.values(quantity).reduce((sum, value) => sum + Number(value || 0), 0),
    [quantity],
  );

  const quote = useMemo(() => {
    const discount = totalQuantity >= 100 ? 0.82 : totalQuantity >= 50 ? 0.9 : 1;
    const unitPrice = Math.max(9, Math.round(selectedProduct.basePrice * discount));
    const subtotal = unitPrice * totalQuantity;
    const serviceFee = Math.round(subtotal * 0.05);
    const logistics = totalQuantity > 0 ? 80 : 0;
    return {
      unitPrice,
      subtotal,
      serviceFee,
      logistics,
      total: subtotal + serviceFee + logistics,
    };
  }, [selectedProduct, totalQuantity]);

