  function leaveCategoryStage() {
    setCategoryInteracting(false);
    setHoveredCategory(null);
  }

  function blurCategoryStage(event) {
    if (!event.currentTarget.contains(event.relatedTarget)) {
      leaveCategoryStage();
    }
  }

  function focusCategory(index) {
    const item = categories[getCategoryIndex(index)];
    setCategoryInteracting(true);
    setHoveredCategory((current) => (current === index ? current : index));
    setSelectedProduct((current) => (current.id === item.id ? current : item));
  }

  function moveWithinCategoryStage(event) {
    setCategoryInteracting(true);
    const stageRect = event.currentTarget.getBoundingClientRect();
    const pointerX = clamp(((event.clientX - stageRect.left) / stageRect.width) * 100, 0, 100);
    const pointerY = clamp(((event.clientY - stageRect.top) / stageRect.height) * 100, 0, 100);
    event.currentTarget.style.setProperty("--dot-cursor-x", `${pointerX}%`);
    event.currentTarget.style.setProperty("--dot-cursor-y", `${pointerY}%`);
    const categoryButton = event.target.closest?.("[data-category-index]");
    if (!categoryButton || !event.currentTarget.contains(categoryButton)) return;
    const index = Number(categoryButton.dataset.categoryIndex);
    if (Number.isInteger(index)) focusCategory(index);
  }

  function handleCategoryWheel(event) {
    const rawDelta = Math.abs(event.deltaX) > Math.abs(event.deltaY) ? event.deltaX : event.deltaY;
    if (Math.abs(rawDelta) < 1) return;

    if (event.cancelable) event.preventDefault();
    event.stopPropagation();
    setCategoryInteracting(true);

    const deltaMultiplier = event.deltaMode === 1
      ? 16
      : event.deltaMode === 2
        ? window.innerHeight
        : 1;
    categoryWheelDeltaRef.current += rawDelta * deltaMultiplier;

    window.clearTimeout(categoryWheelResetTimerRef.current);
    categoryWheelResetTimerRef.current = window.setTimeout(() => {
      categoryWheelDeltaRef.current = 0;
    }, 180);

    if (categoryWheelLockedRef.current || carouselMotion) return;
    if (Math.abs(categoryWheelDeltaRef.current) < 42) return;

    const direction = categoryWheelDeltaRef.current > 0 ? 1 : -1;
    categoryWheelDeltaRef.current = 0;
    categoryWheelLockedRef.current = true;
    rotate(direction);
    setCategoryInteracting(true);

    window.clearTimeout(categoryWheelUnlockTimerRef.current);
    categoryWheelUnlockTimerRef.current = window.setTimeout(() => {
      categoryWheelLockedRef.current = false;
    }, 960);
  }

